function drawRowletRoundOwl(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.2;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 2.8;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Chân cam
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.roundRect(-14, by + 28, 8, 8, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(6,   by + 28, 8, 8, 3); ctx.fill();

  // Thân tròn vo
  ctx.fillStyle = '#e5d0ba';
  ctx.beginPath(); ctx.arc(0, by + 2, 22 * sX, 0, Math.PI * 2); ctx.fill();

  // Kính mắt đôi trắng
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.arc(-10, by - 6, 11, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(10,  by - 6, 11, 0, Math.PI * 2); ctx.fill();

  // Mỏ
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.arc(0, by - 8, 4, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.moveTo(-3, by - 6); ctx.lineTo(0, by - 1); ctx.lineTo(3, by - 6); ctx.fill();

  // Mắt đen
  if (!blink) {
    ctx.fillStyle = '#0f172a';
    ctx.beginPath(); ctx.ellipse(-10, by - 6, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(10,  by - 6, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-11, by - 9, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(9,   by - 9, 2, 0, Math.PI * 2); ctx.fill();
  }

  // Nơ lá xanh
  ctx.fillStyle = '#10b981';
  ctx.beginPath(); ctx.ellipse(-6, by + 12, 6, 4, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(6,  by + 12, 6, 4, 0, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}
